async function liveEtf4(){
 const quotes={},errors=[];
 // Primary: Anue. Keep its live last price when available.
 try{
  const syms=ETF.map(c=>'TWS:'+c+':STOCK').join(',');
  const url='https://ws.api.cnyes.com/ws/api/v1/quote/quotes/'+syms+
            '?column=FORMAT&_='+(Date.now()+'_'+Math.random().toString(36).slice(2));
  const d=await getJSONQuick(url,{
   'User-Agent':'Mozilla/5.0','Referer':'https://www.cnyes.com/',
   'Cache-Control':'no-cache, no-store, max-age=0','Pragma':'no-cache','Accept-Encoding':'identity'
  },4500);
  for(const x of (d?.data||[])){
   const code=String(x?.['200010']||'').trim();if(!ETF.includes(code))continue;
   const last=n(x?.['200026']);
   if(last>0)quotes[code]={ticker:code,name:x?.['200009']||code,last,prevClose:n(x?.['200031']),change:n(x?.['200027']),changePct:n(x?.['200044']),
    open:n(x?.['200032']),high:n(x?.['200033']),low:n(x?.['200034']),volume:n(x?.['200036']),time:null,date:ymdTaipei(),source:'Anue 鉅亨',realtime:true,serverFetchedAt:new Date().toISOString()};
  }
 }catch(e){errors.push('Anue 鉅亨: '+(e.message||String(e)))}

 // Field-level TWSE MIS completion. Anue sometimes has last but omits prev/open/HLV.
 // Fill only missing fields; never overwrite a good Anue last price.
 const needMis=ETF.filter(c=>!(quotes[c]?.last>0)||!(quotes[c]?.prevClose>0)||(twMarketOpenNow()&&!(quotes[c]?.open>0)));
 if(needMis.length){
  try{
   const ex=needMis.map(c=>'tse_'+c+'.tw').join('|'),rows=(await mis(ex)).msgArray||[],by={};
   for(const x of rows){const q=parseMis(x);if(ETF.includes(q.ticker))by[q.ticker]=q}
   for(const c of needMis){
    const q=by[c];if(!q)continue;
    if(!quotes[c]&&q.last>0)quotes[c]={...q,source:'TWSE MIS fallback',realtime:true,serverFetchedAt:new Date().toISOString()};
    else if(quotes[c]){
     const z=quotes[c];
     for(const k of ['prevClose','open','high','low','volume','time','date'])if(!(Number(z[k])>0)&&z[k]!==0&&q[k]!=null)z[k]=q[k];
     if(!(z.last>0)&&q.last>0)z.last=q.last;
     z.source=z.source.includes('Anue')?'Anue 鉅亨＋TWSE欄位補全':'TWSE MIS fallback';
    }
   }
  }catch(e){errors.push('TWSE MIS field fill: '+(e.message||String(e)))}
 }
 // Cash-session open is required by the existing anti-chase ceiling.
 // Some ETF transports return fresh last/prev but leave open blank.
 // Fill ONLY missing session fields from the already-existing Yahoo 1m/meta path.
 // Never overwrite a valid live last price.
 if(twMarketOpenNow()){
  const needOpen=ETF.filter(c=>quotes[c]?.last>0&&!(Number(quotes[c]?.open)>0));
  if(needOpen.length){
   try{
    const ys=await Promise.all(needOpen.map(async c=>[
     c,
     await deadline(yahooTwOne(c,false).catch(()=>null),4200,null)
    ]));
    for(const [c,y] of ys){
     if(!y||!(Number(y.open)>0)||!quotes[c])continue;
     const z=quotes[c];
     z.open=Number(y.open);
     if(!(Number(z.high)>0)&&Number(y.high)>0)z.high=Number(y.high);
     if(!(Number(z.low)>0)&&Number(y.low)>0)z.low=Number(y.low);
     if(!(Number(z.prevClose)>0)&&Number(y.prevClose)>0)z.prevClose=Number(y.prevClose);
     z.openSource='Yahoo Finance 1m/meta';
     z.source=(z.source||'ETF live')+'＋Yahoo開盤補全';
    }
   }catch(e){errors.push('Yahoo ETF open fill: '+(e.message||String(e)))}
  }
 }

 const openRequired=twMarketOpenNow(),now=Date.now(),today=ymdTaipei();
 // Save each complete quote. A single transport wobble may reuse only the same-day quote for <=90 seconds.
 for(const c of ETF){
  const q=quotes[c];
  if(etfQuoteComplete(q,openRequired)){
   q.serverFetchedAt=q.serverFetchedAt||new Date().toISOString();
   ETF_QUOTE_LAST_GOOD[c]={q:{...q},at:Date.parse(q.serverFetchedAt)||now,day:today};
  }
 }
 for(const c of ETF){
  if(etfQuoteComplete(quotes[c],openRequired))continue;
  const lg=ETF_QUOTE_LAST_GOOD[c];
  if(!lg||lg.day!==today||now-lg.at>90000)continue;
  if(!quotes[c])quotes[c]={...lg.q,source:(lg.q.source||'即時')+'｜last-good緩衝',lastGoodFallback:true};
  else{
   const z=quotes[c],q=lg.q;
   for(const k of ['last','prevClose','open','high','low','volume','time','date'])if(!(Number(z[k])>0)&&z[k]!==0&&q[k]!=null)z[k]=q[k];
   z.source=(z.source||q.source||'即時')+'｜last-good欄位緩衝';z.lastGoodFallback=true;
   // If the current transport supplied a fresh last, keep its fresh timestamp; otherwise preserve the old timestamp.
   if(!(z.serverFetchedAt&&Number(z.last)>0))z.serverFetchedAt=q.serverFetchedAt;
  }
 }
 const incomplete=ETF.filter(c=>!etfQuoteComplete(quotes[c],openRequired));
 return{ok:incomplete.length===0,source:'Anue 鉅亨 primary + TWSE field completion + 90s last-good',fetchedAt:new Date().toISOString(),quotes,
  missing:ETF.filter(c=>!quotes[c]?.last),incomplete,errors};
}


