 // Primary: TWSE MIS, one session cookie and moderate-size batches.
 try{
  const nonce=Date.now()+'_'+Math.random().toString(36).slice(2);let cookie='';
  try{
   const r=await deadline(fetch('https://mis.twse.com.tw/stock/index.jsp?_='+nonce,{headers:{'User-Agent':'Mozilla/5.0','Cache-Control':'no-cache','Pragma':'no-cache'}}),1800,null);
   if(r){const m=(r.headers.get('set-cookie')||'').match(/JSESSIONID=[^;]+/i);if(m)cookie=m[0]}
  }catch(_){}
  const chunks=[];for(let i=0;i<codes.length;i+=70)chunks.push(codes.slice(i,i+70));
  const rows=(await mapLimit(chunks,4,async chunk=>{
   try{
    const ex=chunk.map(c=>'tse_'+c+'.tw').join('|'),headers={'User-Agent':'Mozilla/5.0','Referer':'https://mis.twse.com.tw/stock/index.jsp','Cache-Control':'no-cache, no-store, max-age=0','Pragma':'no-cache','Accept-Encoding':'identity'};
    if(cookie)headers.Cookie=cookie;
    const d=await getJSONQuick('https://mis.twse.com.tw/stock/api/getStockInfo.jsp?ex_ch='+encodeURIComponent(ex)+'&json=1&delay=0&_='+(Date.now()+Math.random()),headers,4500);
    return (d?.msgArray||[]).map(x=>{const q=parseMis(x);return{code:q.ticker,last:q.last,prev:q.prevClose,change:Number.isFinite(q.last)&&Number.isFinite(q.prevClose)?q.last-q.prevClose:null,volume:q.volume}})
   }catch(e){errors.push('TWSE:'+((e&&e.message)||e));return[]}
  })).flat();
  for(const q of rows)if(/^[1-9]\d{3}$/.test(q.code)&&q.last>0)by.set(q.code,q);
 }catch(e){errors.push('TWSE MIS:'+((e&&e.message)||e))}

 // Fill only missing stocks from Anue, in smaller batches to avoid long-URL / partial-response failures.
 const missing=codes.filter(c=>!by.has(c)),chunks=[];for(let i=0;i<missing.length;i+=20)chunks.push(missing.slice(i,i+20));
 if(chunks.length){
  const rows=(await mapLimit(chunks,6,async chunk=>{
   try{
    const syms=chunk.map(c=>'TWS:'+c+':STOCK').join(','),url='https://ws.api.cnyes.com/ws/api/v1/quote/quotes/'+syms+'?column=FORMAT&_='+(Date.now()+Math.random());
    const d=await getJSONQuick(url,{'User-Agent':'Mozilla/5.0','Referer':'https://www.cnyes.com/','Cache-Control':'no-cache, no-store, max-age=0','Pragma':'no-cache','Accept-Encoding':'identity'},4000);
    return (d?.data||[]).map(x=>({code:String(x?.['200010']||'').trim(),last:n(x?.['200026']),prev:n(x?.['200031']),change:n(x?.['200027']),volume:n(x?.['200036'])}))
   }catch(e){errors.push('Anue:'+((e&&e.message)||e));return[]}
  })).flat();
  for(const q of rows)if(/^[1-9]\d{3}$/.test(q.code)&&q.last>0&&!by.has(q.code))by.set(q.code,q);
 }

 const eps=1e-9;let up=0,down=0,flat=0,untraded=0,noCompare=0,quoted=0;
 for(const code of codes){
  const q=by.get(code);if(!q||!(q.last>0))continue;quoted++;
  if(!(q.prev>0)){noCompare++;continue}
  const ch=Number.isFinite(q.change)?q.change:q.last-q.prev;
  if(ch>eps)up++;else if(ch<-eps)down++;else flat++;
  if(!(Number.isFinite(q.volume)&&q.volume>0))untraded++;
 }
 const coverage=codes.length?quoted/codes.length:0,valid=up+down+flat;
 if(coverage<.68||valid<500)throw Error(`即時廣度覆蓋不足 ${(coverage*100).toFixed(0)}% / 有效${valid}`);
