 const envSupport=envScore>0?clamp(envScore/100,0,1)*a*.10:0;
 const healthSupport=healthUsable&&Number.isFinite(healthScore)&&healthScore>50?clamp((healthScore-50)/50,0,1)*a*.06:0;
